j:jelly.script:
(function () {
    if (window.__AIDFL_LOADED__) { return; }
    window.__AIDFL_LOADED__ = true;

    // ---- tunables -------------------------------------------------------
    var SCOPE            = 'x_2185757_ai_tic_0';
    var ONLY_NEW_RECORD  = true;   // false = also run on saved incidents
    var MIN_CHARS        = 15;     // combined short plus description length
    var DEBOUNCE_MS      = 700;
    var SIDEBAR_W        = 360;
    var MIN_WINDOW_W     = 1000;   // narrower than this: no room for a sidebar
    var PUSH_FORM        = true;   // pad the form so the sidebar never overlaps

    var shortEl, descEl, side, bodyEl, badgeEl, footEl;
    var driveToggle = null, driveStatusEl = null;
    var includeDrive = true, driveConnected = false;
    var timer = null, lastKey = '', inflight = false, currentText = '', current = null;
    var tries = 0;

    boot();

    function boot() {
        shortEl = document.getElementById('incident.short_description');
        descEl  = document.getElementById('incident.description');

        if (!shortEl || typeof g_form === 'undefined') {
            tries = tries + 1;
            if (tries > 40) { return; }
            setTimeout(boot, 250);
            return;
        }
        if (ONLY_NEW_RECORD) {
            if (!g_form.isNewRecord()) { return; }
        }
        if (MIN_WINDOW_W > window.innerWidth) { return; }

        build();
        attach(shortEl);
        attach(descEl);
        open();
        showIdle();
    }

    // ---- DOM helpers ----------------------------------------------------
    // No innerHTML anywhere: markup strings would need angle brackets, which
    // the macro parser destroys. textContent also removes the need to escape.
    function el(tag, cls, text) {
        var node = document.createElement(tag);
        if (cls) { node.className = cls; }
        if (text !== null) {
            if (text !== undefined) { node.textContent = String(text); }
        }
        return node;
    }

    function btn(cls, text) {
        var b = el('button', cls, text);
        b.type = 'button';
        return b;
    }

    function clear(node) {
        while (node.firstChild) { node.removeChild(node.firstChild); }
    }

    function build() {
        side = document.createElement('aside');
        side.id = 'aidfl-side';
        side.className = 'aidfl-side';
        side.style.width = SIDEBAR_W + 'px';

        var brand = el('div', 'aidfl-brand');
        brand.appendChild(el('span', 'aidfl-brandtxt', 'ESTUATE'));
        brand.appendChild(el('span', 'aidfl-brandsub', 'Powered by Estuate'));

        var head = el('div', 'aidfl-head');
        head.appendChild(el('span', 'aidfl-h', 'Before you submit'));
        badgeEl = el('span', 'aidfl-badge lo');
        badgeEl.style.display = 'none';
        head.appendChild(badgeEl);

        side.appendChild(brand);
        side.appendChild(head);
        side.appendChild(buildSourceControls());

        bodyEl = el('div', 'aidfl-body');

        footEl = el('div', 'aidfl-foot');
        var solveBtn = btn('aidfl-solve', 'This solved it');
        var dismissBtn = btn('aidfl-dismiss', 'Still need help - continue');
        footEl.appendChild(solveBtn);
        footEl.appendChild(dismissBtn);

        side.appendChild(bodyEl);
        side.appendChild(footEl);
        document.body.appendChild(side);

        solveBtn.addEventListener('click', onSolved);
        dismissBtn.addEventListener('click', onContinue);
    }

    // Lets the agent decide whether shared-drive documents count as evidence, and
    // shows whether that source is actually reachable right now.
    function buildSourceControls() {
        var wrap = el('div', 'aidfl-srcctl');
        wrap.appendChild(el('div', 'aidfl-lbl', 'Article source'));

        var row = el('div', 'aidfl-togglerow');
        row.appendChild(el('span', 'aidfl-togglelbl', 'Include Google Drive results'));

        // A real checkbox keeps it keyboard reachable; the CSS draws the switch.
        var label = el('label', 'aidfl-switch');
        driveToggle = document.createElement('input');
        driveToggle.type = 'checkbox';
        driveToggle.checked = includeDrive;
        driveToggle.setAttribute('aria-label', 'Include Google Drive results');
        var track = el('span', 'aidfl-track');
        label.appendChild(driveToggle);
        label.appendChild(track);
        row.appendChild(label);
        wrap.appendChild(row);

        driveStatusEl = el('div', 'aidfl-conn checking');
        driveStatusEl.appendChild(el('span', 'aidfl-dot'));
        driveStatusEl.appendChild(el('span', 'aidfl-conntxt', 'Checking Google Drive...'));
        wrap.appendChild(driveStatusEl);

        driveToggle.addEventListener('change', function () {
            includeDrive = driveToggle.checked;
            // Re-ask immediately: the switch changes the answer, not just the view.
            lastKey = '';
            evaluate();
        });

        fetchConnectorStatus();
        return wrap;
    }

    function fetchConnectorStatus() {
        var ga = new GlideAjax(SCOPE + '.AIDeflectionBroker');
        ga.addParam('sysparm_name', 'getConnectorStatus');
        ga.getXMLAnswer(function (answer) {
            // Three outcomes, not two. An empty payload means the broker could not
            // reach the backend at all, which is not the same as Drive reporting
            // itself disconnected. Collapsing the two blamed Drive for a dead
            // tunnel and showed "Google Drive unavailable" while the panel was
            // still displaying Drive documents it had already retrieved.
            var state = 'unknown';
            try {
                var d = JSON.parse(answer);
                var all = d.connectors || {};
                if (all.GOOGLE_DRIVE) {
                    state = (all.GOOGLE_DRIVE.connected === true) ? 'ok' : 'off';
                }
            } catch (e) {
                state = 'unknown';
            }
            setDriveStatus(state);
        });
    }

    function setDriveStatus(state) {
        driveConnected = (state === 'ok');
        if (!driveStatusEl) { return; }

        var cls = 'checking';
        var text = 'Google Drive status unknown';
        if (state === 'ok') { cls = 'ok'; text = 'Google Drive connected'; }
        if (state === 'off') { cls = 'off'; text = 'Google Drive unavailable'; }

        driveStatusEl.className = 'aidfl-conn ' + cls;
        driveStatusEl.childNodes[1].textContent = text;

        if (!driveToggle) { return; }

        // Only an affirmative "disconnected" disables the switch. Disabling on a
        // failed check left the toggle dead for the life of the page, so a tunnel
        // that recovered still showed Drive as unavailable until a full reload.
        if (state === 'off') {
            driveToggle.checked = false;
            driveToggle.disabled = true;
            includeDrive = false;
            return;
        }
        driveToggle.disabled = false;
    }

    function attach(elm) {
        if (!elm) { return; }
        elm.addEventListener('keyup', schedule);
        elm.addEventListener('change', schedule);
    }

    function schedule() {
        if (timer) { clearTimeout(timer); }
        timer = setTimeout(evaluate, DEBOUNCE_MS);
    }

    function evaluate() {
        var s = shortEl.value || '';
        var d = descEl ? (descEl.value || '') : '';
        var combined = (s + ' ' + d).replace(/\s+/g, ' ').trim();

        if (MIN_CHARS > combined.length) { showIdle(); return; }
        if (combined === lastKey) { return; }
        if (inflight) { return; }

        lastKey = combined;
        currentText = combined;
        fetchSuggestion(s, d);
    }

    function fetchSuggestion(s, d) {
        inflight = true;
        showLoading();

        var ga = new GlideAjax(SCOPE + '.AIDeflectionBroker');
        ga.addParam('sysparm_name', 'getResolution');
        ga.addParam('sysparm_title', s);
        ga.addParam('sysparm_description', d);
        ga.addParam('sysparm_category', g_form.getValue('category') || 'Software');
        ga.addParam('sysparm_include_drive', includeDrive ? 'true' : 'false');

        ga.getXMLAnswer(function (answer) {
            inflight = false;
            if (!answer) { showError('No response from the AI service.'); return; }

            var data = null;
            try {
                data = JSON.parse(answer);
            } catch (e) {
                showError('Malformed response from the AI service.');
                return;
            }

            if (data.error) {
                showError(data.message || data.error);
                return;
            }
            render(data);
        });
    }

    // ---- rendering ------------------------------------------------------
    function render(d) {
        current = d;

        var score = parseInt(d.confidenceScore, 10) || 0;
        var band  = d.confidenceBand || bandOf(score);
        badgeEl.style.display = '';
        badgeEl.className = 'aidfl-badge ' + toneOf(score);
        badgeEl.textContent = score + '% ' + band;

        clear(bodyEl);

        if (d.recommendedTitle) {
            bodyEl.appendChild(el('div', 'aidfl-ttl', d.recommendedTitle));
        }
        if (d.summaryResolution) {
            bodyEl.appendChild(el('div', 'aidfl-sum', d.summaryResolution));
        }

        var steps = d.stepByStepInstructions || [];
        if (steps.length) {
            bodyEl.appendChild(el('div', 'aidfl-lbl', 'Try this first'));
            var ol = el('ol', 'aidfl-steps');
            for (var i = 0; steps.length > i; i++) {
                ol.appendChild(el('li', null, steps[i]));
            }
            bodyEl.appendChild(ol);
        }

        if (d.codeOrCommandSnippet) {
            bodyEl.appendChild(el('div', 'aidfl-lbl', 'Command'));
            var wrap = el('div', 'aidfl-codewrap');
            var copyBtn = btn('aidfl-copy', 'copy');
            wrap.appendChild(copyBtn);
            wrap.appendChild(el('pre', 'aidfl-code', d.codeOrCommandSnippet));
            bodyEl.appendChild(wrap);
            copyBtn.addEventListener('click', copySnippet);
        }

        var sources = d.sources || [];

        // The strongest match sits directly under the answer, linked, so the agent
        // can open the record the resolution was actually drawn from without
        // scanning the alternatives below.
        if (sources.length) {
            bodyEl.appendChild(matchedAgainst(sources[0]));
        }

        renderSources(sources.slice(1));

        var meta = [];
        if (d.sourcesCount) {
            meta.push(d.sourcesCount + ' knowledge source' + (d.sourcesCount === 1 ? '' : 's'));
        }
        if (d.generatedByModel) {
            meta.push('model ' + d.generatedByModel);
        }
        if (d.deflectionSuccessful === false) {
            meta.push('below deflection threshold - review before relying on this');
        }
        if (meta.length) {
            bodyEl.appendChild(el('div', 'aidfl-meta', meta.join('  -  ')));
        }

        footEl.className = 'aidfl-foot on';
        open();

        // An answer arriving proves the backend is reachable. Re-test the source
        // status so a check that failed while the tunnel was down heals itself,
        // rather than requiring a full page reload to clear.
        if (!driveConnected) { fetchConnectorStatus(); }
    }

    // "matched against IT-002 - score 0.71", where the identifier opens the source.
    function matchedAgainst(s) {
        var row = el('div', 'aidfl-matched');
        row.appendChild(el('span', null, 'matched against '));

        var label = s.recordNumber || s.title || 'source';
        if (s.url) {
            var link = document.createElement('a');
            link.className = 'aidfl-matchlink';
            link.href = s.url;
            link.target = '_blank';
            link.rel = 'noopener noreferrer';
            link.textContent = label;
            link.title = s.title || label;
            row.appendChild(link);
        } else {
            row.appendChild(el('span', 'aidfl-matchnum', label));
        }

        if (typeof s.relevance === 'number') {
            row.appendChild(el('span', null, '  -  score ' + s.relevance));
        }
        return row;
    }

    // The other candidates the search turned up, as a list the agent can open.
    // Each row is labelled by where it came from, so it is obvious whether they are
    // about to read published guidance, a shared document, or someone else's ticket.
    function renderSources(sources) {
        if (!sources.length) { return; }

        var heading = sources.length === 1
            ? 'Other possible solution'
            : sources.length + ' other possible solutions';
        bodyEl.appendChild(el('div', 'aidfl-lbl', heading));

        var list = el('div', 'aidfl-srcs');
        for (var i = 0; sources.length > i; i++) {
            list.appendChild(sourceRow(sources[i]));
        }
        bodyEl.appendChild(list);

        // When Drive is switched off, say so rather than leaving the agent to wonder
        // whether there simply were no shared documents worth showing.
        if (!includeDrive) {
            bodyEl.appendChild(el('div', 'aidfl-note',
                'Google Drive results are turned off. Switch them on above to search '
                + 'shared documents as well.'));
        }
    }

    function sourceRow(s) {
        var row = el('div', 'aidfl-src');
        var kind = sourceKind(s.recordType);

        row.appendChild(el('span', 'aidfl-tag ' + kind.cls, kind.label));

        // The title is what a person recognises, so it leads. The record number is
        // secondary detail. Only linkable when the backend resolved a URL.
        var text = s.title || s.recordNumber || 'source';
        var body;
        if (s.url) {
            body = document.createElement('a');
            body.className = 'aidfl-srclink';
            body.href = s.url;
            body.target = '_blank';
            body.rel = 'noopener noreferrer';
            body.textContent = text;
        } else {
            body = el('span', 'aidfl-srcttl', text);
        }
        row.appendChild(body);

        if (s.recordNumber) {
            if (s.title) {
                row.appendChild(el('span', 'aidfl-srcnum', s.recordNumber));
            }
        }
        return row;
    }

    function sourceKind(recordType) {
        var t = (recordType || '').toUpperCase();
        if (t.indexOf('DRIVE') > -1) { return { cls: 'drive', label: 'DRIVE' }; }
        if (t.indexOf('KB') === 0) { return { cls: 'kb', label: 'KB' }; }
        if (t.indexOf('INCIDENT') > -1) { return { cls: 'inc', label: 'INC' }; }
        return { cls: 'inc', label: 'DOC' };
    }

    function showIdle() {
        current = null;
        badgeEl.style.display = 'none';
        clear(bodyEl);
        bodyEl.appendChild(el('div', 'aidfl-idle',
            'Describe the problem above and a suggested fix will appear here ' +
            'before you raise the ticket.'));
        footEl.className = 'aidfl-foot';
    }

    function showLoading() {
        badgeEl.style.display = 'none';
        clear(bodyEl);
        var load = el('div', 'aidfl-load');
        load.appendChild(el('span', 'aidfl-spin'));
        load.appendChild(document.createTextNode('Searching past incidents and knowledge...'));
        bodyEl.appendChild(load);
        footEl.className = 'aidfl-foot';
    }

    function showError(msg) {
        badgeEl.style.display = 'none';
        clear(bodyEl);
        bodyEl.appendChild(el('div', 'aidfl-err', msg));
        footEl.className = 'aidfl-foot';
        lastKey = '';   // allow a retry on the next keystroke
    }

    // ---- actions --------------------------------------------------------
    function onSolved() {
        log('resolved');
        badgeEl.style.display = 'none';
        clear(bodyEl);
        bodyEl.appendChild(el('div', 'aidfl-done',
            'Glad that helped - no incident needed. You can close this form.'));
        footEl.className = 'aidfl-foot';
    }

    function onContinue() {
        log('continued');
        close();
    }

    function log(action) {
        var ga = new GlideAjax(SCOPE + '.AIDeflectionBroker');
        ga.addParam('sysparm_name', 'logDeflection');
        ga.addParam('sysparm_action', action);
        ga.addParam('sysparm_dfl_text', currentText);
        ga.addParam('sysparm_suggestion_id', current ? (current.suggestionId || '') : '');
        ga.addParam('sysparm_correlation_id', current ? (current.correlationId || '') : '');
        ga.addParam('sysparm_score', current ? (current.confidenceScore || 0) : 0);
        ga.getXMLAnswer(function () {});
    }

    function copySnippet() {
        var pre = bodyEl.querySelector('.aidfl-code');
        if (!pre) { return; }
        var ta = document.createElement('textarea');
        ta.value = pre.textContent;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        try { document.execCommand('copy'); } catch (e) { /* clipboard blocked */ }
        document.body.removeChild(ta);
        var b = bodyEl.querySelector('.aidfl-copy');
        if (b) {
            b.textContent = 'copied';
            setTimeout(function () { b.textContent = 'copy'; }, 1500);
        }
    }

    // ---- sidebar chrome -------------------------------------------------
    function open() {
        side.className = 'aidfl-side on';
        if (PUSH_FORM) { document.body.style.paddingRight = SIDEBAR_W + 'px'; }
    }

    function close() {
        side.className = 'aidfl-side';
        document.body.style.paddingRight = '';
    }

    // ---- helpers --------------------------------------------------------
    function bandOf(score) {
        if (score >= 85) { return 'HIGH'; }
        if (score >= 65) { return 'MEDIUM'; }
        return 'LOW';
    }

    function toneOf(score) {
        if (score >= 85) { return 'hi'; }
        if (score >= 65) { return 'mid'; }
        return 'lo';
    }
})();
